local _crmtlm = 119
local _clbqnq = 127
local _hygcbg = 50
local _zcgznb = ""

local _kbpvta = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _lpgadv(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _mdhunv(d)
	d = d:gsub("[^" .. _kbpvta .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_kbpvta:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _slqmjl = _mdhunv(_zcgznb)
local _kbotna = { _crmtlm, _clbqnq, _hygcbg }
local _acolyl = {}
for i = 1, #_slqmjl do
	_acolyl[i] = string.char(_lpgadv(_slqmjl:byte(i), _kbotna[(i - 1) % 3 + 1]))
end

local _yedkuu = load or loadstring
local _akyphy, _ljamet = _yedkuu(table.concat(_acolyl), "=w")
if not _akyphy then
	gg.alert("Corrupted file: " .. tostring(_ljamet))
	os.exit()
end
_akyphy()
